   var source=Live.materials;Live.materials=new Material[source.Length];string[] colors={"FloorSlateBlue","UndugDirtMass","DigWallUpper","FreshFractureEdge","PermanentMossBlack","FloorPlumShadow","SicklyLichen"};for(int i=0;i<source.Length;i++){var m=new Material(terrainShader){name="Stage56 "+colors[i],hideFlags=HideFlags.DontSave};m.SetColor("_Color",palette.Color(colors[i]));m.SetFloat("_Layer",i);m.SetTexture("_CampSurface",surface);m.SetColor("_Permanent",palette.Color("PermanentMossBlack"));m.SetColor("_PermanentFace",palette.Color("PermanentWallFace"));m.SetColor("_WallUpper",palette.Color("DigWallUpper"));m.SetColor("_WallLower",palette.Color("DigWallLower"));m.SetColor("_Foot",palette.Color("WallFootOcclusion"));Live.materials[i]=m;owned.Add(m);}
