  void Bind(){Session.Committed+=OnBatch;}
  void OnBatch(CampBatch batch){long t=System.Diagnostics.Stopwatch.GetTimestamp();Live.Stream.RefreshPhysicalCells(batch.Cells);AcceptedBatches++;ChangedCells+=batch.Cells.Count;MutationMs=StreamingGeometry.Elapsed(t);}
  public void ResetTest(int selected=0){Initialize();long t=System.Diagnostics.Stopwatch.GetTimestamp();Session.Committed-=OnBatch;Session=new CampSession(AuthoredCamp.Create());Live.ReplacePreviewWorld(Session.BindReadOnlyGeometry());Live.Actors.Clear();Bind();AcceptedBatches=ChangedCells=0;ConstructionReplay.Clear();if(selected>=1){Session.Discover();}if(selected>=2)Session.FakeReturn(selected>=3?4:1,5,2);if(selected>=3)for(int i=0;i<4;i++)Session.ConstructNext(out _);if(selected>=4){Session.BuddyDied();}if(selected>=5){for(int i=0;i<4;i++)Session.AddBuddy();for(int i=0;i<6;i++)Session.ConstructNext(out _);}Go(arrival==0?"arrival.first":"run.departure");ResetMs=StreamingGeometry.Elapsed(t);Status="Restored deterministic snapshot "+selected+". Session only.";}
  public void SetFraming(int n){framing=n;CameraStudy.Apply(2);Live.settings.anchor=n==0?.62f:.57f;}
  public void Go(string id){var m=Session.Definition.Marker(id);if(!Session.Active(m.Gate)&&id!="bones"){Status=m.Name+" is locked or reserved.";return;}Live.Teleport(V(m.Interaction));Live.SetPreviewFocus(Live.Position);}
  public void SimulateArrival(){if(arrival==3&&(Session.Deaths==0||Session.Living==0)){Status="Post-death arrival scenario needs a test death and a living Buddy; real succession is not connected.";return;}Go(arrival==0?"arrival.first":"run.departure");Status=new[]{"Intro approach only; no new story sequence","Continue scenario; current session retained, no slot loaded","Return arrival scenario; use Fake Return for expedition inputs","Post-death arrival position only; real succession unconnected"}[arrival];}
  public void FakeReturn(){if(Constructing){Status="Finish construction before returning";return;}Session.FakeReturn(returnBuddies,returnMushrooms,returnShinies);arrival=1;Go("run.departure");Status=$"Preview return: +{returnBuddies} Buddies, +{returnMushrooms} mushrooms, +{returnShinies} shinies. No run or save invoked.";}
  public void DigBedrooms(){if(Constructing)return;long t=System.Diagnostics.Stopwatch.GetTimestamp();Status=Session.BeginConstruction(out string why)?"Buddy approaching authorized bedroom entrance; excavation will update live terrain":why;ConstructionMs=StreamingGeometry.Elapsed(t);}
  public int Dig(Point2 target){if(Vector2.Distance(Live.Position,V(target))>2.2f)return 0;var cells=new List<DualTile>();for(int y=(int)target.Y-1;y<=(int)target.Y+1;y++)for(int x=(int)target.X-1;x<=(int)target.X+1;x++)cells.Add(new DualTile(x,y));return Session.DigPlayer(cells);}
  void Update(){Initialize();Live.Actors.Clear();Live.speed=speed;if(automation)return;var k=Keyboard.current;var m=Mouse.current;if(k!=null&&k.tabKey.wasPressedThisFrame)showPanel=!showPanel;bool over=showPanel&&m!=null&&m.position.ReadValue().x<335;var movement=k==null?Vector2.zero:new Vector2((k.dKey.isPressed?1:0)-(k.aKey.isPressed?1:0),(k.sKey.isPressed?1:0)-(k.wKey.isPressed?1:0));Vector2 aim=Live.Aim;if(m!=null&&Live.Snapshot!=null&&!over){var p=Live.previewCamera.ScreenToWorldPoint(new Vector3(m.position.ReadValue().x,m.position.ReadValue().y,10));aim=V(Live.Snapshot.Unproject(new Point2(p.x,-p.y)))-Live.Position;}if(Live.Ready){var next=Session.Move(P(Live.Position),new Point2(movement.normalized.x*speed*Time.deltaTime,movement.normalized.y*speed*Time.deltaTime),1);Live.TeleportWithoutFocus(V(next));if(aim.sqrMagnitude>.001)Live.Aim=aim.normalized;digTimer-=Time.deltaTime;if(!over&&digTimer<=0&&((m!=null&&m.leftButton.isPressed)||(k!=null&&k.spaceKey.isPressed))){int n=Dig(P(Live.Position+Live.Aim*1.6f));Status=n>0?$"Excavated{n} authorized expansion cells":"Only ordinary expansion dirt accepts player digging. Bedrooms belong to Buddy construction.";digTimer=.15f;}if(k!=null&&k.eKey.wasPressedThisFrame)Interact();}TickResidents(Math.Min(.05,Time.deltaTime));}
  public void TickResidents(double dt){Session.TickSocialMovement(dt);if(!Constructing)return;Session.TickConstruction(dt);Status=Session.ConstructionStatus;}
  public string Interact(){CampMarker nearest=null;double best=2.4;foreach(var m in Session.Definition.Markers){double d=Vector2.Distance(Live.Position,V(m.Interaction));if(d<best&&Session.Active(m.Gate)){nearest=m;best=d;}}if(nearest==null)return Status="Move to a station's small interaction marker and press E.";switch(nearest.Id){case "run.departure":return Status="Run departure is not connected in this test. Leader/successor eligibility remains a production integration gap.";case "fire":Session.Discover();Session.Recover();return Status="Preview Fire visit: recovered flag set; real healing, food, upgrades and saves are not connected.";case "squad":foreach(var r in Session.Residents)if(r.Alive){r.InSquad=!r.InSquad;return Status=r.Id+" preview squad="+r.InSquad+". Production roster UI is unconnected.";}break;case "bones":return Status="Preview memorial: "+Session.Deaths+" fallen Buddy records; succession is unconnected.";case "storage":return Status=$"Preview storage: {Session.Mushrooms} mushrooms / {Session.Shinies} shinies. No campaign resources.";}return Status=nearest.Name+"  /  preview marker only";}
  Batch Add(string name,string color,int order){var go=new GameObject("Stage56 "+name){hideFlags=HideFlags.DontSave};go.transform.SetParent(transform,false);var f=go.AddComponent<MeshFilter>();f.sharedMesh=new Mesh{name=go.name,hideFlags=HideFlags.DontSave};var rr=go.AddComponent<MeshRenderer>();var mat=new Material(Live.materials[(int)PreviewLayer.Gobbo]){hideFlags=HideFlags.DontSave};mat.SetColor("_Color",palette.Color(color));owned.Add(mat);rr.sharedMaterial=mat;rr.sortingOrder=order;var b=new Batch{Data=new PreviewMeshData(name,PreviewLayer.Gobbo),Filter=f,Renderer=rr};batches.Add(b);return b;}
  void LateUpdate(){if(!initialized||Live.Snapshot==null)return;long decorationStart=System.Diagnostics.Stopwatch.GetTimestamp();foreach(var b in batches)b.Data.Clear();foreach(var m in Session.Definition.Markers){var d=Session.Active(m.Gate)?stations.Data:locked.Data;double x=m.Anchor.X,y=m.Anchor.Y;d.Rectangle(x-1.4,y-.7,x+1.4,y+.7);var p=m.Interaction;d.Rectangle(p.X-.25,p.Y-.25,p.X+.25,p.Y+.25);}foreach(var room in Session.Definition.Bedrooms)for(int j=0;j<room.Beds.Count;j++)if(room.FirstSlot+j<=Session.Established){var p=room.Beds[j];beds.Data.Rectangle(p.X-1.1,p.Y-.6,p.X+1.1,p.Y+.6);}foreach(var r in Session.Residents)if(r.Alive){var p=r.Position;buddies.Data.Rectangle(p.X-1.05,p.Y-1.3,p.X+1.05,p.Y+.1);}foreach(var b in batches){b.Renderer.enabled=Live.Ready;Live.Gpu.Draw(b.Data,b.Filter,new ProjectionBounds(new Point2(0,0),new Point2(W,W)),true);}DecorationMs=StreamingGeometry.Elapsed(decorationStart);}
