  public static Vector2 V(Point2 p)=>new Vector2((float)p.X,(float)p.Y);public static Point2 P(Vector2 p)=>new Point2(p.x,p.y);
  void OnDestroy(){if(Session!=null)Session.Committed-=OnBatch;foreach(var b in batches){if(Live!=null&&Live.Gpu!=null)Live.Gpu.Forget(b.Filter);if(b.Filter!=null)DestroyOwned(b.Filter.sharedMesh);}foreach(var m in owned)DestroyOwned(m);DestroyOwned(surface);}
